    $this->hours = (int) round($this->hours * $factor);
    $this->minutes = (int) round($this->minutes * $factor);
    $this->seconds = (int) round($this->seconds * $factor);
    $this->microseconds = (int) round($this->microseconds * $factor);

    return $this;
}

